using System.Linq;

public static class ReportPrinter
{
    // One line per category, "category: total", already sorted by the aggregator.
    public static string Render(string csv)
    {
        var totals = SalesAggregator.CategoryTotals(csv);
        return string.Join("\n", totals.Select(t => $"{t.Category}: {t.Total}"));
    }
}

