using System.Collections.Generic;
using Xunit;

public class SalesAggregatorTests
{
    [Fact]
    public void SumsByCategorySorted()
    {
        var csv = "category,amount\nbooks,500\nfood,250\nbooks,300\n";
        Assert.Equal(
            new List<(string, long)> { ("books", 800), ("food", 250) },
            SalesAggregator.CategoryTotals(csv));
    }

    [Fact]
    public void SkipsInvalidRows()
    {
        var csv = "category,amount\nbooks,500\n,99\n   ,100\ntoys,notanumber\nbooks,-200\n";
        Assert.Equal(
            new List<(string, long)> { ("books", 300) },
            SalesAggregator.CategoryTotals(csv));
    }

    [Fact]
    public void HeaderOnlyIsEmpty()
    {
        Assert.Equal(new List<(string, long)>(), SalesAggregator.CategoryTotals("category,amount\n"));
    }

    [Fact]
    public void IntegratesWithPrinter()
    {
        var csv = "category,amount\nbooks,500\nfood,250\nbooks,300\n";
        Assert.Equal("books: 800\nfood: 250", ReportPrinter.Render(csv));
    }
}

