using System;
using System.Collections.Generic;
using System.Linq;

public static class SalesAggregator
{
    public static List<(string Category, long Total)> CategoryTotals(string csv)
    {
        var totals = new Dictionary<string, long>();
        foreach (var line in csv.Split('\n').Skip(1))
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            var cols = line.Split(',');
            var category = cols[0].Trim();
            if (category.Length == 0) continue;
            if (cols.Length < 2 || !long.TryParse(cols[1].Trim(), out var amount)) continue;
            totals[category] = totals.GetValueOrDefault(category) + amount;
        }
        return totals
            .OrderBy(kv => kv.Key, StringComparer.Ordinal)
            .Select(kv => (kv.Key, kv.Value))
            .ToList();
    }
}

